(4944059, 718887, 94265, '<td valign="top">I love the use of burlap(?) for the background.</td>', 'I love the use of burlap(?) for the background.', '2008-09-09 10:31:49.000000', NULL, 1),
(4944060, 718420, 54478, '<td valign="top">The white balance is a off on this photo. It would have looked great in my opinion if the background was a more pure white.</td>', 'The white balance is a off on this photo. It would have looked great in my opinion if the background was a more pure white.', '2008-09-09 10:32:05.000000', NULL, 1),
(4944061, 719077, 94265, '<td valign="top">I could really see this happen in an ad on TV, the effect is groovy. Well done.</td>', 'I could really see this happen in an ad on TV, the effect is groovy. Well done.', '2008-09-09 10:32:20.000000', NULL, 1),
(4944063, 719107, 94265, '<td valign="top">Lovely soft colours and focus.</td>', 'Lovely soft colours and focus.', '2008-09-09 10:32:37.000000', NULL, 1),
(4944064, 718999, 94265, '<td valign="top">Great crop and I like that white top-bottom border.</td>', 'Great crop and I like that white top-bottom border.', '2008-09-09 10:33:12.000000', NULL, 1),
(4944065, 718093, 94265, '<td valign="top">Nice work, I almost feel cold looking at this! Good composition too.</td>', 'Nice work, I almost feel cold looking at this! Good composition too.', '2008-09-09 10:33:57.000000', NULL, 1),
(4944066, 718703, 54478, '<td valign="top">Nice capture of the dual face.</td>', 'Nice capture of the dual face.', '2008-09-09 10:34:00.000000', NULL, 1),
(4944067, 719023, 94265, '<td valign="top">I think I''d have liked this in colour but it''s a nice shot.</td>', 'I think I''d have liked this in colour but it''s a nice shot.', '2008-09-09 10:34:37.000000', NULL, 1),
(4944068, 719078, 94265, '<td valign="top">Brilliant clarity and nice lighting.</td>', 'Brilliant clarity and nice lighting.', '2008-09-09 10:35:02.000000', NULL, 1),
(4944069, 719073, 94265, '<td valign="top">Hehe this is a good shot, very clear and crisp.</td>', 'Hehe this is a good shot, very clear and crisp.', '2008-09-09 10:35:30.000000', NULL, 1),
(4944070, 719026, 94265, '<td valign="top">Socks aren''t a great attention-grasping subject but the colours are really good, you can''t go wrong with purple!</td>', 'Socks aren''t a great attention-grasping subject but the colours are really good, you can''t go wrong with purple!', '2008-09-09 10:36:15.000000', NULL, 1),
(4944073, 719075, 94265, '<td valign="top">Hmm as a flight company advert it would work but I think calling a plane a product is just a wee bit silly! Good clear shot though, I like the border.</td>', 'Hmm as a flight company advert it would work but I think calling a plane a product is just a wee bit silly! Good clear shot though, I like the border.', '2008-09-09 10:37:36.000000', NULL, 1),
(4944074, 718159, 54478, '<td valign="top">Good capture. It makes me hungry... hehe</td>', 'Good capture. It makes me hungry... hehe', '2008-09-09 10:37:37.000000', NULL, 1),
(4944077, 719057, 94265, '<td valign="top">Classic, looks brilliant, the background and the DOF on it really help make this pop.</td>', 'Classic, looks brilliant, the background and the DOF on it really help make this pop.', '2008-09-09 10:38:11.000000', NULL, 1),
(4944079, 718571, 94265, '<td valign="top">I could see this in a home furnishings catalog. Nice light and centering.</td>', 'I could see this in a home furnishings catalog. Nice light and centering.', '2008-09-09 10:39:10.000000', NULL, 1),
(4944080, 719213, 94265, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2008-09-09 10:39:31.000000', NULL, 1),
(4944081, 718852, 94265, '<td valign="top">Nice crisp clear focus.</td>', 'Nice crisp clear focus.', '2008-09-09 10:40:03.000000', NULL, 1),
(4944083, 718420, 94265, '<td valign="top">I really like the title with this shot, looks great, though I''d have used maybe a cooler light.</td>', 'I really like the title with this shot, looks great, though I''d have used maybe a cooler light.', '2008-09-09 10:40:32.000000', NULL, 1),
(4944084, 717250, 94265, '<td valign="top">Really nice composition, light and colour.</td>', 'Really nice composition, light and colour.', '2008-09-09 10:40:51.000000', NULL, 1),
(4944090, 719069, 94265, '<td valign="top">Nice idea, I like the different colours.</td>', 'Nice idea, I like the different colours.', '2008-09-09 10:41:32.000000', NULL, 1),
(4944092, 718786, 94265, '<td valign="top">My eyes are drawn more to the umbrella (being in colour) rather than the camera but I really like the idea.</td>', 'My eyes are drawn more to the umbrella (being in colour) rather than the camera but I really like the idea.', '2008-09-09 10:42:18.000000', NULL, 1),
(4944095, 718945, 94265, '<td valign="top">Great idea and composition, light on the clear gem is a bit harsh. Well worth an 8 though.</td>', 'Great idea and composition, light on the clear gem is a bit harsh. Well worth an 8 though.', '2008-09-09 10:42:46.000000', NULL, 1),
(4944097, 718550, 94265, '<td valign="top">Really good clarity and the lighting is spot-on.</td>', 'Really good clarity and the lighting is spot-on.', '2008-09-09 10:43:19.000000', NULL, 1),
(4944101, 719005, 94265, '<td valign="top">I kinda like how the line of the background fades on the other side of the lens and the focus is really nice and sharp.</td>', 'I kinda like how the line of the background fades on the other side of the lens and the focus is really nice and sharp.', '2008-09-09 10:44:15.000000', NULL, 1),
(4944102, 719079, 94265, '<td valign="top">Maybe a wee bit too close to the subject but the light is great, I like how you''ve captured the brand name in there too.</td>', 'Maybe a wee bit too close to the subject but the light is great, I like how you''ve captured the brand name in there too.', '2008-09-09 10:44:47.000000', NULL, 1),
(4944105, 719064, 98141, '<td valign="top">Nice framing, great colors and shine in the right places.</td>', 'Nice framing, great colors and shine in the right places.', '2008-09-09 10:47:11.000000', NULL, 1),
(4944107, 718852, 98141, '<td valign="top">Nice framing, simple, good product shot.</td>', 'Nice framing, simple, good product shot.', '2008-09-09 10:47:52.000000', NULL, 1),
(4944108, 718990, 98141, '<td valign="top">Great color, nice brand closeup, good choice.</td>', 'Great color, nice brand closeup, good choice.', '2008-09-09 10:48:12.000000', NULL, 1),
(4944109, 718662, 98141, '<td valign="top">Clever. I think I would prefer it if the two rocks in front of the diamonds weren''t there - they are a little distracting from the subject. I like the black.</td>', 'Clever. I think I would prefer it if the two rocks in front of the diamonds weren''t there - they are a little distracting from the subject. I like the black.', '2008-09-09 10:49:28.000000', NULL, 1),
(4944111, 718833, 98141, '<td valign="top">Cool product to photograph, nice lines and good framing.</td>', 'Cool product to photograph, nice lines and good framing.', '2008-09-09 10:50:38.000000', NULL, 1),
(4944112, 719042, 98141, '<td valign="top">Good framing, shows the product well, but nice and simple.</td>', 'Good framing, shows the product well, but nice and simple.', '2008-09-09 10:51:17.000000', NULL, 1),
(4944115, 719070, 98141, '<td valign="top">This is lovely, nice sparkle in the jewelry and good use of color and brand name.</td>', 'This is lovely, nice sparkle in the jewelry and good use of color and brand name.', '2008-09-09 10:52:13.000000', NULL, 1),
(4944116, 718855, 98141, '<td valign="top">Makes me want some, therefore I declare it effective advertising.</td>', 'Makes me want some, therefore I declare it effective advertising.', '2008-09-09 10:52:55.000000', NULL, 1),
(4944120, 719133, 98141, '<td valign="top">Clever, makes me want pumpkin pie. I might suggest closing the bottle.</td>', 'Clever, makes me want pumpkin pie. I might suggest closing the bottle.', '2008-09-09 10:54:32.000000', NULL, 1),
(4944123, 719229, 98141, '<td valign="top">Nice shot of gear in action.</td>', 'Nice shot of gear in action.', '2008-09-09 10:54:59.000000', NULL, 1),
(4944125, 718754, 98141, '<td valign="top">Very nice, I like the framing on this and think there''s a great connection between foreground and background with the use of the sparkling wine and fruit in both places.</td>', 'Very nice, I like the framing on this and think there''s a great connection between foreground and background with the use of the sparkling wine and fruit in both places.', '2008-09-09 10:56:10.000000', NULL, 1),
(4944128, 719114, 98141, '<td valign="top">I would like this better if it showcased the product a little more. Here we, the buyer, can''t see it in its entirety so it''s hard to tell if we want to buy it or not.</td>', 'I would like this better if it showcased the product a little more. Here we, the buyer, can''t see it in its entirety so it''s hard to tell if we want to buy it or not.', '2008-09-09 10:57:12.000000', NULL, 1),
(4944133, 717357, 94265, '<td valign="top">Awesome crop, clarity and colours.</td>', 'Awesome crop, clarity and colours.', '2008-09-09 10:57:32.000000', NULL, 1),
(4944134, 719070, 94265, '<td valign="top">Really good lighting, you''ve made the bracelet/necklace? and the ribbon look very nice. I''d have kept the whole name in focus though.</td>', 'Really good lighting, you''ve made the bracelet/necklace? and the ribbon look very nice. I''d have kept the whole name in focus though.', '2008-09-09 10:57:36.000000', NULL, 1),
(4944136, 719222, 94265, '<td valign="top">This looks absolutely fantastic.</td>', 'This looks absolutely fantastic.', '2008-09-09 10:57:39.000000', NULL, 1),
(4944137, 719140, 94265, '<td valign="top">Lovely blend of colour in the background.</td>', 'Lovely blend of colour in the background.', '2008-09-09 10:57:43.000000', NULL, 1),
(4944138, 718174, 94265, '<td valign="top">Good composition.</td>', 'Good composition.', '2008-09-09 10:57:47.000000', NULL, 1),
(4944139, 718058, 94265, '<td valign="top">Good vibrant shot, very much catalog material (pardon the pun.)</td>', 'Good vibrant shot, very much catalog material (pardon the pun.)', '2008-09-09 10:57:51.000000', NULL, 1),
(4944140, 719173, 94265, '<td valign="top">Great idea and I''d say nearly perfectly done, though that little white speck on the left of the bottle''s reflection bugs me a bit.</td>', 'Great idea and I''d say nearly perfectly done, though that little white speck on the left of the bottle''s reflection bugs me a bit.', '2008-09-09 10:57:54.000000', NULL, 1),
(4944141, 719119, 94265, '<td valign="top">Wow, great colour and use of water.</td>', 'Wow, great colour and use of water.', '2008-09-09 10:57:58.000000', NULL, 1),
(4944142, 719080, 94265, '<td valign="top">The subject isn''t really grabbing me, that background is pretty good though.</td>', 'The subject isn''t really grabbing me, that background is pretty good though.', '2008-09-09 10:58:03.000000', NULL, 1),
(4944143, 717989, 94265, '<td valign="top">The background goes perfectly, this is straight out of a Christmas catalog.</td>', 'The background goes perfectly, this is straight out of a Christmas catalog.', '2008-09-09 10:58:06.000000', NULL, 1),
(4944144, 717194, 94265, '<td valign="top">Just stunning.</td>', 'Just stunning.', '2008-09-09 10:58:10.000000', NULL, 1),
(4944145, 718874, 94265, '<td valign="top">Interesting subject choice! Very modern, good job.</td>', 'Interesting subject choice! Very modern, good job.', '2008-09-09 10:58:15.000000', NULL, 1),
(4944146, 718770, 94265, '<td valign="top">Light''s a wee bit bright in the foreground a wee bit dim in back but you score points for comedic value! Very funny.</td>', 'Light''s a wee bit bright in the foreground a wee bit dim in back but you score points for comedic value! Very funny.', '2008-09-09 10:58:19.000000', NULL, 1),
(4944147, 718778, 94265, '<td valign="top">Very nice, I like how the blue background is a soft material like the dog. Works well.</td>', 'Very nice, I like how the blue background is a soft material like the dog. Works well.', '2008-09-09 10:58:21.000000', NULL, 1),
(4944148, 719229, 94265, '<td valign="top">Very professional looking shot, I must say.</td>', 'Very professional looking shot, I must say.', '2008-09-09 10:58:30.000000', NULL, 1),
(4944149, 718980, 94265, '<td valign="top">Looks amazing, very effective.</td>', 'Looks amazing, very effective.', '2008-09-09 10:58:34.000000', NULL, 1),
(4944150, 717194, 98141, '<td valign="top">Nice closeup on brand and dials, shows the detail and quality of the piece.</td>', 'Nice closeup on brand and dials, shows the detail and quality of the piece.', '2008-09-09 10:58:38.000000', NULL, 1),
(4944151, 718774, 94265, '<td valign="top">What a brilliant shot, looks great.</td>', 'What a brilliant shot, looks great.', '2008-09-09 10:58:42.000000', NULL, 1),
(4944152, 719126, 94265, '<td valign="top">I love this! He''s like one of those ladies with unfeasibly white teeth standing next to a product with their hands held out the exact same way. Fantastic!</td>', 'I love this! He''s like one of those ladies with unfeasibly white teeth standing next to a product with their hands held out the exact same way. Fantastic!', '2008-09-09 10:58:46.000000', NULL, 1),
(4944153, 719209, 94265, '<td valign="top">Really nice lighting.</td>', 'Really nice lighting.', '2008-09-09 10:58:51.000000', NULL, 1),
(4944155, 719227, 94265, '<td valign="top">Wow, now that is awesome. If I could vote, I''d give it 10 right away. <br/> <br/>Edit: Now I can!</td>', 'Wow, now that is awesome. If I could vote, I''d give it 10 right away.  Edit: Now I can!', '2008-09-09 10:59:07.000000', NULL, 1),
(4944156, 718855, 94265, '<td valign="top">This could be used commercially, really nice job.</td>', 'This could be used commercially, really nice job.', '2008-09-09 10:59:12.000000', NULL, 1),
(4944157, 718868, 94265, '<td valign="top">Whatever the stuff in the bottom left is, it kinda distracts and the crop is just a wee bit tight on top.</td>', 'Whatever the stuff in the bottom left is, it kinda distracts and the crop is just a wee bit tight on top.', '2008-09-09 10:59:16.000000', NULL, 1),
(4944158, 718956, 94265, '<td valign="top">Great colours, very eye-catching.</td>', 'Great colours, very eye-catching.', '2008-09-09 10:59:20.000000', NULL, 1),
(4944159, 719224, 94265, '<td valign="top">Glare on the wall is a wee bit harsh. I like the crop on the teddy though.</td>', 'Glare on the wall is a wee bit harsh. I like the crop on the teddy though.', '2008-09-09 10:59:24.000000', NULL, 1),
(4944162, 719024, 94265, '<td valign="top">This really looks like a screenshot from a proper advert, great job.</td>', 'This really looks like a screenshot from a proper advert, great job.', '2008-09-09 10:59:32.000000', NULL, 1),
(4944163, 719138, 94265, '<td valign="top">This seems more like just a flower shot than a product shot but it''s very attractive.</td>', 'This seems more like just a flower shot than a product shot but it''s very attractive.', '2008-09-09 10:59:39.000000', NULL, 1),
(4944165, 719121, 94265, '<td valign="top">Without the title, I''d have said this was simply a horse shot (but still a good one.) Very crisp and clear, lovely colours.</td>', 'Without the title, I''d have said this was simply a horse shot (but still a good one.) Very crisp and clear, lovely colours.', '2008-09-09 10:59:49.000000', NULL, 1),
(4944166, 717893, 94265, '<td valign="top">I love the old-style feel of this.</td>', 'I love the old-style feel of this.', '2008-09-09 10:59:53.000000', NULL, 1),
(4944167, 719127, 98141, '<td valign="top">I love this one, good framing, good colors, good setup with the leaves, bag lunch, pencils and apple. Really evokes the feeling of going back to school in fall. Picnic table is a nice touch. Good inclusion of brand name.</td>', 'I love this one, good framing, good colors, good setup with the leaves, bag lunch, pencils and apple. Really evokes the feeling of going back to school in fall. Picnic table is a nice touch. Good inclusion of brand name.', '2008-09-09 11:00:10.000000', NULL, 1),
(4944168, 718484, 98141, '<td valign="top">This is a nice shot, but I don''t think that it evokes the sexiness of what GUESS usually stands for. If I needed a product shot for my GUESS line, I would want it to evoke how people are going to feel when they wear my product. This, to me, says that GUESS is simple product for a simply woman.</td>', 'This is a nice shot, but I don''t think that it evokes the sexiness of what GUESS usually stands for. If I needed a product shot for my GUESS line, I would want it to evoke how people are going to feel when they wear my product. This, to me, says that GUESS is simple product for a simply woman.', '2008-09-09 11:02:24.000000', NULL, 1),
(4944172, 718571, 98141, '<td valign="top">What I like about this is that it''s hard to tell how big the object actually is. It could be a miniature or it could be the size of, well, an elephant.</td>', 'What I like about this is that it''s hard to tell how big the object actually is. It could be a miniature or it could be the size of, well, an elephant.', '2008-09-09 11:03:42.000000', NULL, 1),
(4944185, 719058, 94265, '<td valign="top">I can''t help but feel that a product shot of any kind should be closer to the product than this. Nice shot though, the sky is pretty and contrasts nicely with the green field.</td>', 'I can''t help but feel that a product shot of any kind should be closer to the product than this. Nice shot though, the sky is pretty and contrasts nicely with the green field.', '2008-09-09 11:11:11.000000', NULL, 1),
(4944186, 719211, 94265, '<td valign="top">Love the contrasting green in the background, nice job.</td>', 'Love the contrasting green in the background, nice job.', '2008-09-09 11:11:14.000000', NULL, 1),
(4944187, 718536, 94265, '<td valign="top">Cropped a bit tight at the bottom but it''s nice and bright, good placement of the items.</td>', 'Cropped a bit tight at the bottom but it''s nice and bright, good placement of the items.', '2008-09-09 11:11:17.000000', NULL, 1),
(4944188, 718132, 94265, '<td valign="top">Very classic, I could see this on the wall of a high-end jewellery store.</td>', 'Very classic, I could see this on the wall of a high-end jewellery store.', '2008-09-09 11:11:22.000000', NULL, 1),
(4944189, 718838, 94265, '<td valign="top">Great sharp and clear shot.</td>', 'Great sharp and clear shot.', '2008-09-09 11:11:25.000000', NULL, 1),
(4944190, 718469, 94265, '<td valign="top">Classic idea brought beautifully to life.</td>', 'Classic idea brought beautifully to life.', '2008-09-09 11:11:29.000000', NULL, 1),
(4944191, 718947, 94265, '<td valign="top">I really like the composition.</td>', 'I really like the composition.', '2008-09-09 11:11:32.000000', NULL, 1),
(4944192, 719117, 94265, '<td valign="top">I love Dasani, this shot makes me want a bottle! Great clear shot, I think I''d prefer it without the base under the bottle though.</td>', 'I love Dasani, this shot makes me want a bottle! Great clear shot, I think I''d prefer it without the base under the bottle though.', '2008-09-09 11:11:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4944193, 718716, 94265, '<td valign="top">Looks dangerous....! Good light.</td>', 'Looks dangerous....! Good light.', '2008-09-09 11:11:38.000000', NULL, 1),
(4944195, 719127, 94265, '<td valign="top">I really like the composition.</td>', 'I really like the composition.', '2008-09-09 11:11:42.000000', NULL, 1),
(4944287, 718786, 30982, '<td valign="top">My favorite of this challenge.  Lovely job creating the memory - it looks like one.</td>', 'My favorite of this challenge.  Lovely job creating the memory - it looks like one.', '2008-09-09 12:24:22.000000', NULL, 1),
(4944290, 719070, 30982, '<td valign="top">Nice use of shallow DOF, and well designed layout for this shot.</td>', 'Nice use of shallow DOF, and well designed layout for this shot.', '2008-09-09 12:25:07.000000', NULL, 1),
(4944293, 718945, 30982, '<td valign="top">Good use of high key, very clean layout.  The blown bit in the diamond itself might not be a good thing for a product ad, but the overall effect of the shot is very good.</td>', 'Good use of high key, very clean layout.  The blown bit in the diamond itself might not be a good thing for a product ad, but the overall effect of the shot is very good.', '2008-09-09 12:25:49.000000', NULL, 1),
(4944294, 719057, 30982, '<td valign="top">Excellent - well thought out, nicely set out, and the high key works very well here.</td>', 'Excellent - well thought out, nicely set out, and the high key works very well here.', '2008-09-09 12:26:08.000000', NULL, 1),
(4944295, 719211, 30982, '<td valign="top">Very cool with the heart-shaped bokeh!</td>', 'Very cool with the heart-shaped bokeh!', '2008-09-09 12:26:22.000000', NULL, 1),
(4944296, 717194, 30982, '<td valign="top">Very nice product shot, but definitely make wonder why in the world anyone would spend 50K on a wristwatch?</td>', 'Very nice product shot, but definitely make wonder why in the world anyone would spend 50K on a wristwatch?', '2008-09-09 12:27:50.000000', NULL, 1),
(4944298, 718780, 30982, '<td valign="top">What a weird looking flower!  I could see this in a seed or flower catalog, but I think you''d need a crisper, slightly more contrasty and head-on version of the flower to really show the potential customer what they''d be getting.</td>', 'What a weird looking flower!  I could see this in a seed or flower catalog, but I think you''d need a crisper, slightly more contrasty and head-on version of the flower to really show the potential customer what they''d be getting.', '2008-09-09 12:29:06.000000', NULL, 1),
(4944304, 718872, 30982, '<td valign="top">Nice use of the shells as background material, but it''s actually kind of difficult to tell what the product is.  It looks like a bracelet of sorts, but with glass in it, or something that distorts the stuff around/behind it.  I''m also not sure what the keychain-like thing is in the foreground.  I think this is a case where a bit wider view, perhaps a bit more from the top, or with the object tilted more toward the camera, might help portray your subject better.</td>', 'Nice use of the shells as background material, but it''s actually kind of difficult to tell what the product is.  It looks like a bracelet of sorts, but with glass in it, or something that distorts the stuff around/behind it.  I''m also not sure what the keychain-like thing is in the foreground.  I think this is a case where a bit wider view, perhaps a bit more from the top, or with the object tilted more toward the camera, might help portray your subject better.', '2008-09-09 12:31:16.000000', NULL, 1),
(4944306, 719149, 30982, '<td valign="top">It kind of looks like a conversation between the stone and the smoke, which is cool.  For a product shot, though, that may be confusing to a buyer.  Nicely lit and exposed.</td>', 'It kind of looks like a conversation between the stone and the smoke, which is cool.  For a product shot, though, that may be confusing to a buyer.  Nicely lit and exposed.', '2008-09-09 12:31:57.000000', NULL, 1),
(4944308, 719075, 30982, '<td valign="top">Aww, c''mon, throw in the crew and I''ll consider it...  :-)  Nice clean shot.</td>', 'Aww, c''mon, throw in the crew and I''ll consider it...  :-)  Nice clean shot.', '2008-09-09 12:32:27.000000', NULL, 1),
(4944320, 718469, 30982, '<td valign="top">A nice background/choice to display the product - provides a very good setting.  Composition is good, but the technicals of lighting/contrast could use just a bit of work to really make this stand out.  I''ve discovered that reds are very hard to shoot and adjust in post processing - they tend to "blow" with just about anything you do to them, and not sure how to fix this.</td>', 'A nice background/choice to display the product - provides a very good setting.  Composition is good, but the technicals of lighting/contrast could use just a bit of work to really make this stand out.  I''ve discovered that reds are very hard to shoot and adjust in post processing - they tend to "blow" with just about anything you do to them, and not sure how to fix this.', '2008-09-09 12:35:35.000000', NULL, 1),
(4944325, 719227, 30982, '<td valign="top">A very nifty idea with the lighting, but I think for the purposes of this challenge you''d need a label on the bottle to sell the "product".  That said, I like the concept that we''re sold the need to drink bottled water - and for that, the anonymity of the bottle is well suited.</td>', 'A very nifty idea with the lighting, but I think for the purposes of this challenge you''d need a label on the bottle to sell the "product".  That said, I like the concept that we''re sold the need to drink bottled water - and for that, the anonymity of the bottle is well suited.', '2008-09-09 12:37:22.000000', NULL, 1),
(4944327, 719140, 30982, '<td valign="top">Pretty good shot - I really like the soft color and the background you used here.  Just a touch more sharpness on the product itself - primarily the name - would make this pretty worthy of an actual ad.</td>', 'Pretty good shot - I really like the soft color and the background you used here.  Just a touch more sharpness on the product itself - primarily the name - would make this pretty worthy of an actual ad.', '2008-09-09 12:38:21.000000', NULL, 1),
(4944329, 718183, 30982, '<td valign="top">While it''s clearly recognizable as the vaulted emblem of a very expensive automobile, I find myself wanting just a wee bit more depth of field - just enough to bring one paw into focus.  I do like the choice of B&amp;W here.</td>', 'While it''s clearly recognizable as the vaulted emblem of a very expensive automobile, I find myself wanting just a wee bit more depth of field - just enough to bring one paw into focus.  I do like the choice of B&W here.', '2008-09-09 12:39:50.000000', NULL, 1),
(4944333, 718502, 30982, '<td valign="top">I like your choice of lighting here - almost echos that of the figure on the label.  On my laptop I can see a bit of noise in the background along the light trail, but my laptop is very much on the lighter end of the scale.</td>', 'I like your choice of lighting here - almost echos that of the figure on the label.  On my laptop I can see a bit of noise in the background along the light trail, but my laptop is very much on the lighter end of the scale.', '2008-09-09 12:41:10.000000', NULL, 1),
