(4955287, 718132, 67237, '<td valign="top">How much does it cost? :-)</td>', 'How much does it cost? :-)', '2008-09-14 23:35:40.000000', NULL, 1),
(4955289, 718980, 67237, '<td valign="top">good executed photo, imho it would hardly appear like this in a catalog, since it does not depict the actual look of the product.</td>', 'good executed photo, imho it would hardly appear like this in a catalog, since it does not depict the actual look of the product.', '2008-09-14 23:36:52.000000', NULL, 1),
(4955290, 718873, 98022, '<td valign="top">Nice image. Good lighting and DOF.</td>', 'Nice image. Good lighting and DOF.', '2008-09-14 23:37:07.000000', NULL, 1),
