(4955292, 719133, 98022, '<td valign="top">Good job. Great idea to have jack-o-lantern in background. Good DOF making product stand out.</td>', 'Good job. Great idea to have jack-o-lantern in background. Good DOF making product stand out.', '2008-09-14 23:39:51.000000', NULL, 1),
(4955346, 718956, 90474, '<td valign="top">I like the photo, but I think that a product shot, as it would appear in a catalog, would show the product in maximum detail, and evenly exposed.</td>', 'I like the photo, but I think that a product shot, as it would appear in a catalog, would show the product in maximum detail, and evenly exposed.', '2008-09-15 00:08:11.000000', NULL, 1),
(4955347, 718867, 90474, '<td valign="top">The cropped bottom lost a point.</td>', 'The cropped bottom lost a point.', '2008-09-15 00:08:13.000000', NULL, 1),
