(4955349, 719149, 90474, '<td valign="top">As a product shot, it could have used a little more DOF.  7</td>', 'As a product shot, it could have used a little more DOF.  7', '2008-09-15 00:08:19.000000', NULL, 1),
(4955350, 719211, 90474, '<td valign="top">I think that the tea could have been slightly higher in the frame, or a little less crop on the bottom, but very well done.</td>', 'I think that the tea could have been slightly higher in the frame, or a little less crop on the bottom, but very well done.', '2008-09-15 00:08:22.000000', NULL, 1),
