(4961035, 719069, 33736, '<td valign="top">I''m quite surprised that this didn''t land higher - could be lack of product identification, but it''s a wonderful image.</td>', 'I''m quite surprised that this didn''t land higher - could be lack of product identification, but it''s a wonderful image.', '2008-09-18 00:30:21.000000', NULL, 0),
(4961219, 718980, 71121, '<td valign="top">Great shot! On the side like you did it communicates an invisible force that draws the cologne to whatever is on the side. Just like any other force creates an opposite one, the cologne also pulls the thing on the side to it. <br/> <br/>- I would have loved if the thing on the side would have been the naked skin of a beautiful woman. Isn''t that what colognes are for? :)<br/></td>', 'Great shot! On the side like you did it communicates an invisible force that draws the cologne to whatever is on the side. Just like any other force creates an opposite one, the cologne also pulls the thing on the side to it.  - I would have loved if the thing on the side would have been the naked skin of a beautiful woman. Isn''t that what colognes are for? :)', '2008-09-18 04:30:03.000000', NULL, 0),
(4961983, 719227, 94265, '<td valign="top">This is gorgeous, should''ve ranked much higher.</td>', 'This is gorgeous, should''ve ranked much higher.', '2008-09-18 15:22:40.000000', NULL, 0),
